import Product from "./Product";

function ShopView() {
    return ( 
        <>
        <div class="container"><div class="shopTitle"><h1>Магазин.</h1></div></div>
        <div class="productsTitle"><h2>Товары</h2></div>
        <div>
            <Product price={100} name={"дилдо"} category={"алгем"}/>
        </div>
        </>
     );
}

export default ShopView;
